namespace Noct.Tests;

/// <summary>
/// Locates the reference material generated by build/make-test-audio.ps1. A missing directory fails
/// loudly instead of skipping, so a test run can never pass without having checked any audio.
/// </summary>
internal static class TestData
{
    private static readonly Lazy<string> Directory_ = new(Locate);

    public static string Directory => Directory_.Value;

    public static string Flac(string name) => Path.Combine(Directory, name + ".flac");

    public static string PcmPath(string name) => Path.Combine(Directory, name + ".pcm");

    /// <summary>Reference samples exactly as they were given to the Xiph encoder.</summary>
    public static int[] ReferenceSamples(string name, int bitsPerSample)
    {
        var bytes = File.ReadAllBytes(PcmPath(name));
        var width = (bitsPerSample + 7) / 8;
        var samples = new int[bytes.Length / width];
        for (var i = 0; i < samples.Length; i++)
        {
            var value = 0;
            for (var b = 0; b < width; b++)
            {
                value |= bytes[(i * width) + b] << (8 * b);
            }

            var shift = 32 - (width * 8);
            samples[i] = shift > 0 ? (value << shift) >> shift : value;
        }

        return samples;
    }

    private static string Locate()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null)
        {
            var candidate = Path.Combine(directory.FullName, "artifacts", "testaudio");
            if (System.IO.Directory.Exists(candidate))
            {
                return candidate;
            }

            directory = directory.Parent;
        }

        throw new DirectoryNotFoundException(
            "artifacts/testaudio not found. Run build/make-test-audio.ps1 to generate the reference FLAC files.");
    }
}
